        pd.text((2,(i-1)*80+15),ident,font=font,fill='black');totals.update(dict(new_corner_control_pixels=count,new_confirmed_blank_pixels=blank_count,long_faint_candidates=stats['long_faint_candidates_accepted'],replaced_whole_fragments=stats['whole_old_fragments_replaced'],native_detail_pixels=stats['native_detail_pixels'],exported_paths=stats['export_paths']));rows.append(dict(id=ident,split='4张开发/训练图' if ident in lock['development_and_router_train_ids'] else '16张未参与本轮训练的旧图回归',statistics=stats,new_corner_control_pixels=count,new_confirmed_blank_pixels=blank_count))
